def clamp(lo; hi): if . < lo then lo elif . > hi then hi else . end;
def clampScore: clamp(0; 100);

. | .scores | map(clampScore)

def formatValue: if . >= 1000 then tostring + "K" else tostring end;
def tag(_label): {label: _label, value: .};

. | .records | map({name: .name, value: .value | formatValue, status: if .level > 0 then "active" else "idle" end}) | sort_by(.name)

def classify: if . >= 90 then "excellent" elif . >= 70 then "good" elif . >= 50 then "average" else "poor" end;
def scale(factor): . * factor | floor;

. | .students | map(.weight as $w | {name: .name, adjusted: .score | scale($w), grade: .score | scale($w) | classify}) | sort_by(.name)

def parity: if . % 2 == 0 then "even" else "odd" end;
def classify: if . >= 100 then "large" elif . >= 10 then "medium" else "small" end;

. | .records | unique_by(.key) | length as $total | map({key: .key, value: .value, class: .value | classify, parity: .value | parity}) as $processed | {total: $total, min_value: ($processed | min_by(.value) | .value), max_value: ($processed | max_by(.value) | .value), entries: ($processed | sort_by(.key))}

